import{_ as t,o as r,c as a,a0 as o}from"./chunks/framework.CR-yHhk1.js";const g=JSON.parse('{"title":"Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundaries.md","filePath":"explanation/boundaries.md"}'),s={name:"explanation/boundaries.md"};function n(i,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h1><p>What sepia owns — mechanism — and the neighbors it deliberately doesn&#39;t.</p><h2 id="owns" tabindex="-1">Owns <a class="header-anchor" href="#owns" aria-label="Permalink to &quot;Owns&quot;">​</a></h2><ul><li>The <strong>canonical session IR</strong> and every store→IR mapping.</li><li><strong>Store drivers</strong> — per-agent <code>SessionRepository</code> adapters over the driver wire.</li><li>The <strong>local session plane</strong>: attach, prompt, cancel, permission resolution, restore/rewind, lock/liveness probes.</li><li><strong>Agent configs</strong>: the <code>AgentConfig</code> IR, <code>sepia config</code> ops, and the <code>type: sepia-config</code> tamias driver.</li><li>The <strong><code>sepia serve</code> wire</strong> — the embedding contract orchestrators spawn.</li><li>Session <strong>conversion</strong> between agents (<code>sepia convert</code>) and the <code>sepia-meta</code> overlay store.</li></ul><h2 id="doesn-t-own" tabindex="-1">Doesn&#39;t own <a class="header-anchor" href="#doesn-t-own" aria-label="Permalink to &quot;Doesn&#39;t own&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Neighbor</th><th>Owns instead</th></tr></thead><tbody><tr><td><a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a></td><td><strong>Policy</strong> — who may act on a session, when, from where: lock registry, takeover arbitration, multi-node merge/route/queue. Peregrin spawns <code>sepia serve</code>; it never links the session plane.</td></tr><tr><td>Agent CLIs themselves</td><td>Devin, Cline, Claude Code, Cursor own their stores and runtimes; sepia reads/writes through drivers and ACP.</td></tr><tr><td><a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a></td><td>Distribution — the <code>sepia</code> command is a pack <code>bins[]</code> shim; tamias owns fetch/install/service lifecycle.</td></tr><tr><td><a href="https://9aia.com/pavo/" target="_blank" rel="noreferrer">pavo</a></td><td>Surfaces — <code>tamias-driver-sepia</code> renders read-only views proxying <code>sepia serve</code>; the wire stays the contract.</td></tr><tr><td><a href="https://github.com/9aia/hypha" target="_blank" rel="noreferrer">hypha</a> / <a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin entity plane</a></td><td>Sessions appear there as <code>kind=&quot;sepia-session&quot;</code> entities via the <code>sepia-peregrin</code> adapter — the entity substrate itself is hypha&#39;s.</td></tr></tbody></table><p>The rule of thumb: if a feature needs a daemon, a multi-machine view, or arbitration between actors, it belongs to peregrin. If it needs a stable wire other repos embed against, it belongs here.</p>',7)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
